function parse(input: unknown): string[] {
    return (input + "").split("")
}

function to(chart: Record<string, string>) {
    return (input: string) => chart[input]
}

export const sup = (input: unknown): string =>
    parse(input).map(to(superscripts)).join("")

export const supChars = Object.keys(superscripts).join("")

export const sub = (input: unknown): string =>
    parse(input).map(to(subscripts)).join("")

export const subChars = Object.keys(subscripts).join("")
